CREATE TABLE IF NOT EXISTS shipping_zones (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS shipping_zone_countries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,shipping_zone_id BIGINT UNSIGNED NOT NULL,country_code VARCHAR(2) NOT NULL,UNIQUE KEY zone_country(shipping_zone_id,country_code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS shipping_methods (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,carrier VARCHAR(120) NULL,code VARCHAR(80) NOT NULL,description VARCHAR(500) NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,UNIQUE KEY shipping_method_code(code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS shipping_rates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,shipping_zone_id BIGINT UNSIGNED NOT NULL,shipping_method_id BIGINT UNSIGNED NOT NULL,rate DECIMAL(12,2) NOT NULL DEFAULT 0,free_shipping_min DECIMAL(12,2) NULL,estimated_days_min INT NULL,estimated_days_max INT NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,KEY rate_zone(shipping_zone_id),KEY rate_method(shipping_method_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
-- Shipments and shipment_events are defined canonically in shipping_fulfillment.sql.
-- This file intentionally contains only shipping zones, countries, methods and rates.
